/// Whether `name` is a form lifecycle event in this snapshot.
#[must_use]
pub fn is_form_lifecycle_event(name: &str) -> bool {
    FORM_LIFECYCLE_EVENTS.binary_search(&name).is_ok()
}

/// The per-table event forms of
/// [11](../../../docs/specs/11-surface-javascript.md).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TableEvent {
    /// `<table_fieldname>_add`.
    Add,
    /// `<table_fieldname>_remove`.
    Remove,
    /// `before_<table_fieldname>_remove`.
    BeforeRemove,
    /// `<table_fieldname>_delete`.
    Delete,
    /// `<table_fieldname>_move`.
    Move,
    /// `<table_fieldname>_on_form_rendered`.
    OnFormRendered,
}

/// Split a per-table event key into the `Table` fieldname it names and the
/// event.
///
/// The fieldname is returned unchecked: whether the DocType has such a `Table`
/// field is a schema question, and this crate does not hold the schema.
#[must_use]
pub fn table_event(key: &str) -> Option<(&str, TableEvent)> {
    if let Some(rest) = key.strip_prefix("before_")
        && let Some(fieldname) = rest.strip_suffix("_remove")
    {
        return Some((fieldname, TableEvent::BeforeRemove));
    }
    if let Some(fieldname) = key.strip_suffix("_remove") {
        return Some((fieldname, TableEvent::Remove));
    }
    if let Some(fieldname) = key.strip_suffix("_add") {
        return Some((fieldname, TableEvent::Add));
    }
    // `grid.js` and `grid_row.js` trigger all six; the first three alone left
    // `_delete`, `_move` and `_on_form_rendered` handlers reported as dead
    // ([32](../../../docs/specs/32-testing.md)).
    if let Some(fieldname) = key.strip_suffix("_delete") {
        return Some((fieldname, TableEvent::Delete));
    }
    if let Some(fieldname) = key.strip_suffix("_move") {
        return Some((fieldname, TableEvent::Move));
    }
    if let Some(fieldname) = key.strip_suffix("_on_form_rendered") {
        return Some((fieldname, TableEvent::OnFormRendered));
    }
    None
}

/// What a hook's value is expected to name — the schemas of
/// [12](../../../docs/specs/12-surface-hooks.md).
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum Schema {
    /// `Path(Callable)`.
    Callable,
    /// A file path, resolved as an asset ([07](../../../docs/specs/07-dotted-paths.md)).
    File,
    /// `Map<DocTypeName, Map<DocEvent, Path | [Path]>>`.
    DocEvents,
    /// `Map<DocTypeName, Path(Class)>`.
    MapToClass,
    /// `Map<DocTypeName, [Path(Class)]>`.
    MapToClasses,
    /// `Map<DocTypeName, Path(Callable)>`.
    MapToCallable,
    /// `Map<DocTypeName, File | [File]>`.
    MapToFile,
    /// `Map<Path(Whitelisted), Path(Callable)>`.
    MapPathToPath,
    /// `Map<Frequency, [Path]>`, with a `cron` sub-map.
    Scheduler,
    /// `[DocTypeName | {dt, filters}]`.
    Fixtures,
    /// `{methods: [Path], filters: [Path]}`.
    Jinja,
    /// `[{from_route, to_route}]`.
    Routes,
    /// `[AppName]`.
    AppNames,
    /// A known hook with no schema worth checking. Present, never reported.
    Unknown,
}

